            { Field: "Due date",    Failed: IsBlank(dpDue.SelectedDate),                  Message: "Choose a due date" },
            { Field: "Due date",    Failed: dpDue.SelectedDate < Today(),                 Message: "Due date cannot be in the past" },
            { Field: "Amount",      Failed: !IsNumeric(txtAmount.Text),                   Message: "Amount must be a number" },
            { Field: "Reason",      Failed: ddCategory.Selected.Value = "Other" && IsBlank(Trim(txtReason.Text)),
