create-a-reusable-notification-pattern.formulaOrCode:
// App.Formulas: message catalogue and a user-defined function
nfMsg = {
    Saved:       "Your changes were saved.",
    Submitted:   "Request submitted. You will get an email when it is reviewed.",
    Deleted:     "Item deleted.",
    NoAccess:    "You do not have permission to do that. Contact the app owner.",
    Offline:     "You appear to be offline. Try again when you are connected.",
    Generic:     "Something went wrong. Try again, and contact support if it continues."
};

fnFriendlyError(msg: Text): Text =
    If(
        "403" in msg || "access" in Lower(msg),            nfMsg.NoAccess,
        "network" in Lower(msg) || !Connection.Connected,  nfMsg.Offline,
        "required" in Lower(msg),                          "A required field is missing: " & msg,
        nfMsg.Generic
    );

// Using it
IfError(
    Patch(Requests, varRecord, { Status: { Value: "Submitted" } });
    Notify(nfMsg.Submitted, NotificationType.Success, 4000),
    Notify(fnFriendlyError(FirstError.Message), NotificationType.Error, 8000);
    Trace("Submit failed", TraceSeverity.Error, { Message: FirstError.Message, Source: FirstError.Source, Record: varRecord.ID })
)

// App.OnError: catch anything not handled locally
Notify(fnFriendlyError(FirstError.Message), NotificationType.Error, 8000);
Trace("Unhandled error", TraceSeverity.Error, { Message: FirstError.Message, Source: FirstError.Source })

// Conventions
// Success 3-4 seconds | Warning 6 seconds | Error 8 seconds or 0 to stay until dismissed
// Without user-defined functions: keep the same If() in a hidden label or a component output.

filter-galleries-by-current-user.formulaOrCode:
