    )
);

// Show the checklist for a parent
SortByColumns(Filter('Checklist Items', ParentId = varParent.ID), "SortOrder")

// Avoid duplicates if the button is pressed again
// Wrap steps 2 and 3 in:  If(IsEmpty(Filter('Checklist Items', ParentId = varParent.ID)), ... )

use-concat-to-summarize-selected-rows.formulaOrCode:
// Gallery with a checkbox per row
chkSelect.OnCheck   : Collect(colSelected, ThisItem)
chkSelect.OnUncheck : Remove(colSelected, LookUp(colSelected, ID = ThisItem.ID))
chkSelect.Default   : ThisItem.ID in colSelected.ID

// Comma-separated titles
Concat(colSelected, Title, ", ")

// "A, B and C"
With(
    { n: CountRows(colSelected) },
    If(
        n = 0, "Nothing selected",
        n = 1, First(colSelected).Title,
        Concat(FirstN(colSelected, n - 1), Title, ", ") & " and " & Last(colSelected).Title
    )
)

// Summary with a count and a total
CountRows(colSelected) & " items selected, total " & Text(Sum(colSelected, Amount), "$#,##0.00")

// One per line
Concat(colSelected, "• " & Title & " (" & Text(Amount, "$#,##0") & ")", Char(10))

// HTML list for an email body or HTML text control
"<ul>" & Concat(colSelected, "<li>" & Title & "</li>") & "</ul>"

// Combo box selections and multi-value columns
Concat(cmbTags.SelectedItems, Value, "; ")
Concat(ThisItem.Categories, Value, ", ")                  // multi-choice column
Concat(ThisItem.Reviewers, DisplayName, ", ")             // multi-person column
Concat(ThisItem.Reviewers, Email, ";")                    // recipients for an email

// Distinct values only
Concat(Distinct(colSelected, Category.Value), Value, ", ")

// Save the summary
Patch(Requests, varRecord, { SelectedItemsSummary: Concat(colSelected, Title, "; ") })

build-a-compact-power-apps-audit-note.formulaOrCode:
// Save button OnSelect
With(
    {
        changes: Concat(
            Filter(
                Table(
                    { Field: "Status",   Old: varRecord.Status.Value,           New: ddStatus.Selected.Value },
                    { Field: "Priority", Old: varRecord.Priority.Value,         New: ddPriority.Selected.Value },
                    { Field: "Owner",    Old: varRecord.AssignedTo.DisplayName, New: cmbOwner.Selected.DisplayName },
                    { Field: "Due date", Old: Text(varRecord.DueDate, "d mmm yyyy"), New: Text(dpDue.SelectedDate, "d mmm yyyy") }
                ),
                Coalesce(Old, "") <> Coalesce(New, "")
            ),
            Field & ": " & Coalesce(Old, "(blank)") & " → " & Coalesce(New, "(blank)"),
            "; "
        )
    },
    If(
        IsBlank(changes),
        Notify("Nothing was changed", NotificationType.Information),

        // Option A: newest line first in a plain multi-line column
        Set(varRecord,
            Patch(Requests, varRecord, {
                Status:     ddStatus.Selected,
                Priority:   ddPriority.Selected,
                DueDate:    dpDue.SelectedDate,
                AuditNotes: Text(Now(), "yyyy-mm-dd hh:mm") & " " & User().FullName & " - " & changes &
                            If(!IsBlank(varRecord.AuditNotes), Char(10) & Left(varRecord.AuditNotes, 60000))
            })
        );

        // Option B: one row per save in a history list (better for reporting)
        Patch('Request History', Defaults('Request History'), {
            Title:     changes,
            RequestId: varRecord.ID,
            ChangedBy: User().Email,
            ChangedOn: Now()
        })
    )
)

// Show recent activity on the record
FirstN(SortByColumns(Filter('Request History', RequestId = varRecord.ID), "ChangedOn", SortOrder.Descending), 10)

