    Notify("Notes saved", NotificationType.Success)
)

// Display formatted (HTML text control)
htmlNotes.HtmlText : varRecord.Notes

// Plain-text preview in a gallery
Left(PlainText(ThisItem.Notes), 120) & If(Len(PlainText(ThisItem.Notes)) > 120, "...")

// Treat an editor that only holds empty tags as blank
IsBlank(Trim(PlainText(rteNotes.HtmlText)))

// Append a dated entry above existing notes
Patch(Requests, varRecord, {
    Notes: "<p><b>" & Text(Now(), "d mmm yyyy hh:mm") & " - " & User().FullName & "</b></p>" &
           rteNotes.HtmlText & "<hr>" & Coalesce(varRecord.Notes, "")
})

// Edit form: the data card's Update property
rteNotes.HtmlText

// Convert plain text with line breaks to simple HTML before saving
"<p>" & Substitute(EncodeHTML(txtPlain.Text), Char(10), "<br>") & "</p>"

patch-a-generated-request-number-after-c.formulaOrCode:
// Custom form: create, then write the reference
IfError(
    Set(varNew,
        Patch(Requests, Defaults(Requests), {
            Title: txtTitle.Text,
            Category: ddCategory.Selected
        })
    );
    Set(varNew,
        Patch(Requests, varNew, {
            RequestNumber: "REQ-" & Text(Today(), "yyyy") & "-" & Text(varNew.ID, "00000")
        })
    );
    Notify("Request " & varNew.RequestNumber & " created", NotificationType.Success);
    Navigate(scrConfirmation),
    Notify("Could not create the request: " & FirstError.Message, NotificationType.Error)
)

// Edit form: use OnSuccess
frmRequest.OnSuccess :
    Set(varNew,
        Patch(Requests, frmRequest.LastSubmit, {
            RequestNumber: "REQ-" & Text(frmRequest.LastSubmit.ID, "00000")
        })
    );
    Navigate(scrConfirmation)

// Prefix by category
With(
    { prefix: Switch(ddCategory.Selected.Value, "Hardware", "HW", "Software", "SW", "Access", "AC", "GEN") },
    prefix & "-" & Text(varNew.ID, "00000")
)

// No second write: a calculated column in SharePoint is not possible (ID is not available to
// calculated columns), but a flow can set the number on create:
//   concat('REQ-', formatNumber(triggerBody()?['ID'], '00000'))

// Find by reference later (RequestNumber indexed)
LookUp(Requests, RequestNumber = Upper(Trim(txtFind.Text)))

