patch-a-sharepoint-location-text-bundle.formulaOrCode:
Columns
  Latitude (Number, 6 decimals) | Longitude (Number, 6 decimals)
  LocationText (Single line)    | MapLink (Hyperlink) | CapturedOn (Date and time)

// Screen.OnVisible: start the location signal, and stop it when leaving
Enable(Location)              // OnHidden : Disable(Location)

// Capture button OnSelect
If(
    IsBlank(Location.Latitude),
    Notify("Location is not available. Check that location access is allowed for Power Apps.", NotificationType.Warning),
    UpdateContext({
        locLat: Round(Location.Latitude, 6),
        locLng: Round(Location.Longitude, 6),
        locCapturedOn: Now()
