txtAddress.Default : AddressInput1.SelectedLocationFreeformAddress

patch-approval-metadata-from-a-button.formulaOrCode:
Columns: Status (Choice) | Approver (Person) | ApprovedBy (Person) | ApprovedOn (Date and time) | ApprovalComment (Multi-line)

// Approve button OnSelect
With(
    { current: LookUp(Requests, ID = varRecord.ID) },      // read the latest values
    If(
        current.Status.Value <> "Pending approval",
        Notify("This request has already been " & Lower(current.Status.Value) & ".", NotificationType.Warning);
        Set(varRecord, current),

        Lower(current.Approver.Email) <> Lower(User().Email),
        Notify("Only " & current.Approver.DisplayName & " can approve this request.", NotificationType.Error),

        IfError(
            Set(varRecord,
                Patch(Requests, current, {
                    Status: { Value: "Approved" },
                    ApprovedBy: {
                        '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                        Claims: "i:0#.f|membership|" & Lower(User().Email),
                        DisplayName: User().FullName,
                        Email: User().Email,
                        Department: "", JobTitle: "", Picture: ""
                    },
                    ApprovedOn: Now(),
                    ApprovalComment: Trim(txtComment.Text)
                })
            );
            Notify("Request approved", NotificationType.Success),
            Notify("Could not save the approval: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// Button state
btnApprove.Visible     : varRecord.Status.Value = "Pending approval" && Lower(varRecord.Approver.Email) = Lower(User().Email)
btnApprove.DisplayMode : If(locBusy, DisplayMode.Disabled, DisplayMode.Edit)

// Reject uses the same Patch with Status "Rejected" and a required comment.

patch-a-reopen-request-action.formulaOrCode:
Columns: Status | ClosedOn | Resolution | ReopenCount (Number) | ReopenReason | LastReopenedOn | ActivityLog

// Reopen button
Visible :
    varRecord.Status.Value = "Closed"
    && DateDiff(varRecord.ClosedOn, Now(), TimeUnit.Days) <= 14          // reopen window
    && (Lower(varRecord.Author.Email) = Lower(User().Email) || nfIsAgent)

OnSelect : UpdateContext({ locReopen: true })           // shows a dialog with txtReason

// Confirm in the dialog
If(
    Len(Trim(txtReason.Text)) < 10,
    Notify("Say briefly why the request needs to be reopened.", NotificationType.Error),
    IfError(
        Set(varRecord,
            Patch(Requests, LookUp(Requests, ID = varRecord.ID), {
                Status:         { Value: "Reopened" },
                ClosedOn:       Blank(),
                Resolution:     Blank(),
                ReopenCount:    Coalesce(varRecord.ReopenCount, 0) + 1,
                ReopenReason:   Trim(txtReason.Text),
                LastReopenedOn: Now(),
                ActivityLog:    Text(Now(), "yyyy-mm-dd hh:mm") & " " & User().FullName & " reopened: " & Trim(txtReason.Text) &
                                Char(10) & "Previous resolution: " & Coalesce(varRecord.Resolution, "(none)") &
                                If(!IsBlank(varRecord.ActivityLog), Char(10) & varRecord.ActivityLog)
            })
        );
        Reset(txtReason); UpdateContext({ locReopen: false });
        Notify("Request reopened", NotificationType.Success),
        Notify("Could not reopen: " & FirstError.Message, NotificationType.Error)
    )
)

// After the window has passed
lblReopenHint.Text : "This request was closed more than 14 days ago. Create a new request and mention " & varRecord.RequestNumber & "."

// Report: Filter(Requests, ReopenCount > 0)

patch-a-cancelled-request-status-with-re.formulaOrCode:
Columns: Status | CancelReason (Choice) | CancelNote (Multi-line) | CancelledBy (Text) | CancelledOn (Date and time)

// Who can cancel, and when
btnCancelRequest.Visible :
    !(varRecord.Status.Value in ["Completed", "Cancelled", "Rejected"])
    && (Lower(varRecord.Author.Email) = Lower(User().Email) || nfIsAdmin)

btnCancelRequest.OnSelect : UpdateContext({ locCancel: true })

// Dialog controls
ddReason.Items : ["No longer needed", "Submitted by mistake", "Duplicate request", "Requirements changed", "Other"]
txtNote.HintText : If(ddReason.Selected.Value = "Other", "Tell us more (required)", "Add a note (optional)")

// Confirm
If(
    IsBlank(ddReason.Selected.Value),
    Notify("Choose a reason", NotificationType.Error),
    ddReason.Selected.Value = "Other" && IsBlank(Trim(txtNote.Text)),
    Notify("Add a note to explain", NotificationType.Error),
    IfError(
        Set(varRecord,
            Patch(Requests, LookUp(Requests, ID = varRecord.ID), {
                Status:       { Value: "Cancelled" },
                CancelReason: { Value: ddReason.Selected.Value },
                CancelNote:   Trim(txtNote.Text),
                CancelledBy:  User().Email,
                CancelledOn:  Now()
            })
        );
        UpdateContext({ locCancel: false });
        Reset(ddReason); Reset(txtNote);
        Notify("Request cancelled", NotificationType.Success);
        Back(),
        Notify("Could not cancel: " & FirstError.Message, NotificationType.Error)
    )
)

// Show the outcome on the detail screen
lblCancelled.Visible : varRecord.Status.Value = "Cancelled"
lblCancelled.Text    : "Cancelled on " & Text(varRecord.CancelledOn, "d mmm yyyy") & ": " & varRecord.CancelReason.Value

// Follow-up in a flow (trigger condition on Status = Cancelled): withdraw pending approvals,
// close child tasks and tell the assignee.

patch-a-delegated-owner-field.formulaOrCode:
// People picker (combo box)
cmbNewOwner.Items               : Office365Users.SearchUserV2({ searchTerm: cmbNewOwner.SearchText, top: 10, isSearchTermRequired: true }).value
cmbNewOwner.DisplayFields       : ["DisplayName", "Mail"]
cmbNewOwner.SearchFields        : ["DisplayName"]
cmbNewOwner.SelectMultiple      : false

// Reassign button OnSelect
If(
    IsBlank(cmbNewOwner.Selected.Mail),
    Notify("Choose the new owner", NotificationType.Error),
    Lower(cmbNewOwner.Selected.Mail) = Lower(varRecord.Owner.Email),
    Notify("That person already owns this item", NotificationType.Warning),
    IfError(
        Set(varRecord,
            Patch(Requests, LookUp(Requests, ID = varRecord.ID), {
                Owner: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                    Claims: "i:0#.f|membership|" & Lower(cmbNewOwner.Selected.Mail),
                    DisplayName: cmbNewOwner.Selected.DisplayName,
                    Email: cmbNewOwner.Selected.Mail,
                    Department: "", JobTitle: "", Picture: ""
                },
                PreviousOwnerEmail: varRecord.Owner.Email,
                ReassignedOn: Now(),
                ReassignNote: Trim(txtNote.Text)
            })
        );
        Reset(cmbNewOwner);
        Notify("Reassigned to " & varRecord.Owner.DisplayName, NotificationType.Success),
        Notify("Could not reassign: " & FirstError.Message, NotificationType.Error)
    )
)

// Temporary delegate instead of a change of owner
Patch(Requests, varRecord, {
    Delegate: locDelegatePerson,          // a person record built the same way as Owner above
    DelegateUntil: dpUntil.SelectedDate
})

// "My work" then includes delegated items
Filter(Requests, Owner.Email = gblUserEmail || (Delegate.Email = gblUserEmail && DelegateUntil >= Today()))

// Clear the delegate
Patch(Requests, varRecord, { Delegate: Blank(), DelegateUntil: Blank() })

patch-a-priority-change-with-history-not.formulaOrCode:
Columns: Priority (Choice: Low, Normal, High, Urgent) | PriorityHistory (Multi-line, plain) | PriorityChangedOn

// Rank helper (App.Formulas)
nfPriorityRank = Table(
    { Name: "Low", Rank: 1 }, { Name: "Normal", Rank: 2 }, { Name: "High", Rank: 3 }, { Name: "Urgent", Rank: 4 }
);

// Save button OnSelect
With(
    {
        oldP: varRecord.Priority.Value,
        newP: ddPriority.Selected.Value,
        oldRank: LookUp(nfPriorityRank, Name = varRecord.Priority.Value).Rank,
        newRank: LookUp(nfPriorityRank, Name = ddPriority.Selected.Value).Rank
    },
    If(
        oldP = newP,
        Notify("Priority is already " & oldP, NotificationType.Information),

        newRank > oldRank && Len(Trim(txtReason.Text)) < 10,
        Notify("Give a reason for raising the priority.", NotificationType.Error),

        newP = "Urgent" && !nfIsTeamLead,
        Notify("Only a team lead can set Urgent.", NotificationType.Error),

        IfError(
            Set(varRecord,
                Patch(Requests, LookUp(Requests, ID = varRecord.ID), {
                    Priority: { Value: newP },
                    PriorityChangedOn: Now(),
                    PriorityHistory:
                        Text(Now(), "yyyy-mm-dd hh:mm") & " " & User().FullName & ": " & oldP & " → " & newP &
                        If(!IsBlank(Trim(txtReason.Text)), " (" & Trim(txtReason.Text) & ")") &
                        If(!IsBlank(varRecord.PriorityHistory), Char(10) & varRecord.PriorityHistory)
                })
            );
            Reset(txtReason);
            Notify("Priority changed to " & newP, NotificationType.Success),
            Notify("Could not change priority: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// Dropdown default
ddPriority.Default : varRecord.Priority.Value

// History display
lblHistory.Text : Coalesce(varRecord.PriorityHistory, "No priority changes")

patch-a-due-date-extension-request.formulaOrCode:
Columns: DueDate | OriginalDueDate | ExtensionStatus (Choice: None, Requested, Approved, Declined)
         RequestedDueDate | ExtensionReason | ExtensionCount (Number) | ExtensionDecidedBy (Text)

// Owner: request an extension
If(
    IsBlank(dpNewDue.SelectedDate) || dpNewDue.SelectedDate <= varRecord.DueDate,
    Notify("Choose a date later than the current due date.", NotificationType.Error),
    DateDiff(varRecord.DueDate, dpNewDue.SelectedDate, TimeUnit.Days) > 30,
    Notify("Extensions are limited to 30 days. Talk to your manager about a longer change.", NotificationType.Error),
    Len(Trim(txtReason.Text)) < 15,
    Notify("Explain why more time is needed.", NotificationType.Error),
    Set(varRecord,
        Patch(Actions, LookUp(Actions, ID = varRecord.ID), {
            ExtensionStatus:  { Value: "Requested" },
            RequestedDueDate: dpNewDue.SelectedDate,
            ExtensionReason:  Trim(txtReason.Text),
            OriginalDueDate:  Coalesce(varRecord.OriginalDueDate, varRecord.DueDate)
        })
    );
    Notify("Extension requested", NotificationType.Success)
)

// Manager: approve
Set(varRecord,
    Patch(Actions, LookUp(Actions, ID = varRecord.ID), {
        DueDate:            varRecord.RequestedDueDate,
        ExtensionStatus:    { Value: "Approved" },
        ExtensionCount:     Coalesce(varRecord.ExtensionCount, 0) + 1,
        ExtensionDecidedBy: User().Email
    })
)

// Manager: decline (due date unchanged)
Patch(Actions, varRecord, { ExtensionStatus: { Value: "Declined" }, ExtensionDecidedBy: User().Email })

// Button visibility
btnRequest.Visible : Lower(varRecord.Owner.Email) = Lower(User().Email) && varRecord.ExtensionStatus.Value <> "Requested"
btnApprove.Visible : varRecord.ExtensionStatus.Value = "Requested" && Lower(varRecord.Manager.Email) = Lower(User().Email)

// Display
lblDue.Text : Text(varRecord.DueDate, "d mmm yyyy") &
    If(Coalesce(varRecord.ExtensionCount, 0) > 0,
       " (extended " & varRecord.ExtensionCount & " time(s), originally " & Text(varRecord.OriginalDueDate, "d mmm") & ")")

// Manager's queue
Filter(Actions, ExtensionStatus.Value = "Requested", Manager.Email = gblUserEmail)

patch-a-project-code-lookup-safely.formulaOrCode:
// Option A: user picks from a searchable combo box bound to the reference list
cmbProject.Items        : Filter(Projects, IsActive = true, StartsWith(Title, cmbProject.SearchText))
cmbProject.DisplayFields: ["Title", "ProjectName"]

Patch(Requests, varRecord, {
    Project: { Id: cmbProject.Selected.ID, Value: cmbProject.Selected.Title }
})

// Option B: user types or scans a code
With(
    { target: LookUp(Projects, Title = Upper(Trim(txtCode.Text))) },
    If(
        IsBlank(Trim(txtCode.Text)),
        Notify("Enter a project code", NotificationType.Error),
        IsBlank(target),
        Notify("Project " & Upper(Trim(txtCode.Text)) & " was not found.", NotificationType.Error),
        target.IsActive = false,
        Notify(target.Title & " is closed and cannot be used.", NotificationType.Error),
        IfError(
            Set(varRecord,
                Patch(Requests, varRecord, { Project: { Id: target.ID, Value: target.Title } })
            );
            Notify("Linked to " & target.Title & " - " & target.ProjectName, NotificationType.Success),
            Notify("Could not link the project: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// Combo box default when editing
cmbProject.DefaultSelectedItems :
    If(IsBlank(varRecord.Project.Id), Blank(), LookUp(Projects, ID = varRecord.Project.Id))

// Clear the lookup
Patch(Requests, varRecord, { Project: Blank() })

// Show extra columns from the target
LookUp(colProjects, ID = ThisItem.Project.Id).ProjectManager.DisplayName

// Filter by lookup (delegable on the Id)
Filter(Requests, Project.Id = cmbProject.Selected.ID)

patch-a-risk-score-field-from-sliders.formulaOrCode:
// Sliders: sldLikelihood and sldImpact, Min 1, Max 5
sldLikelihood.Default : Coalesce(varRecord.Likelihood, 1)
sldImpact.Default     : Coalesce(varRecord.Impact, 1)

// Labels beside the sliders
lblLikelihood.Text : Switch(sldLikelihood.Value, 1, "Rare", 2, "Unlikely", 3, "Possible", 4, "Likely", 5, "Almost certain")
lblImpact.Text     : Switch(sldImpact.Value, 1, "Negligible", 2, "Minor", 3, "Moderate", 4, "Major", 5, "Severe")

// Live score and rating (named formulas or hidden labels)
sldLikelihood.Value * sldImpact.Value                                   // score, 1 to 25
With({ s: sldLikelihood.Value * sldImpact.Value },
     If(s >= 15, "High", s >= 8, "Medium", "Low"))                      // rating

lblScore.Text : "Score " & (sldLikelihood.Value * sldImpact.Value)
conRating.Fill :
    With({ s: sldLikelihood.Value * sldImpact.Value },
         If(s >= 15, RGBA(196, 49, 75, 1), s >= 8, RGBA(255, 185, 0, 1), RGBA(16, 124, 16, 1)))

// Save
With(
    { s: sldLikelihood.Value * sldImpact.Value },
    If(
        s >= 15 && IsBlank(Trim(txtMitigation.Text)),
        Notify("A high risk needs a mitigation plan.", NotificationType.Error),
        IfError(
            Set(varRecord,
                Patch(Risks, Coalesce(varRecord, Defaults(Risks)), {
                    Title:      txtTitle.Text,
                    Likelihood: sldLikelihood.Value,
                    Impact:     sldImpact.Value,
                    RiskScore:  s,
                    RiskRating: { Value: If(s >= 15, "High", s >= 8, "Medium", "Low") },
                    Mitigation: txtMitigation.Text,
                    ScoredOn:   Now()
                })
            );
            Notify("Risk saved", NotificationType.Success),
            Notify("Could not save: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// 5 x 5 heat map: a gallery of 25 cells, each counting risks
CountRows(Filter(colRisks, Likelihood = ThisItem.L && Impact = ThisItem.I))

patch-a-calculated-display-summary-field.formulaOrCode:
