patch-a-requester-department-snapshot.formulaOrCode:
Columns: RequesterEmail | RequesterDepartment | RequesterJobTitle | RequesterOffice | RequesterManagerEmail (all text)

// App.OnStart: read the profile once
Concurrent(
    Set(gblMe, Office365Users.MyProfileV2()),
    Set(gblMyManager, IfError(Office365Users.ManagerV2(User().Email), Blank()))
);

// Submit for myself
Patch(Requests, Defaults(Requests), {
    Title:                 txtTitle.Text,
    RequesterEmail:        Lower(gblMe.mail),
    RequesterDepartment:   Coalesce(gblMe.department, "Unknown"),
    RequesterJobTitle:     gblMe.jobTitle,
    RequesterOffice:       gblMe.officeLocation,
    RequesterManagerEmail: Lower(gblMyManager.mail)
})

// Submit on behalf of someone else (people picker cmbRequester)
With(
    {
        p: Office365Users.UserProfileV2(cmbRequester.Selected.Mail),
        m: IfError(Office365Users.ManagerV2(cmbRequester.Selected.Mail), Blank())
    },
    Patch(Requests, Defaults(Requests), {
        Title:                 txtTitle.Text,
        RequesterEmail:        Lower(p.mail),
        RequesterDepartment:   Coalesce(p.department, "Unknown"),
        RequesterJobTitle:     p.jobTitle,
        RequesterOffice:       p.officeLocation,
        RequesterManagerEmail: Lower(m.mail)
    })
)

// Show on the form before submitting, read-only
lblDept.Text : "Department: " & Coalesce(gblMe.department, "Not set in the directory")

// Reports and filters use the snapshot (delegable, index the column)
Filter(Requests, RequesterDepartment = ddDept.Selected.Value)

// Do not update the snapshot on later edits: only set these fields when creating.

patch-a-manager-approval-comment.formulaOrCode:
Columns: Manager (Person) | Status | ManagerComment (Multi-line, plain) | ManagerDecisionOn

// Decision buttons set what is being decided
btnApprove.OnSelect : UpdateContext({ locDecision: "Approved" })
btnReject.OnSelect  : UpdateContext({ locDecision: "Rejected" })
btnReturn.OnSelect  : UpdateContext({ locDecision: "Returned" })

// Comment box
txtComment.HintText : Switch(locDecision,
    "Rejected", "Why is this rejected? The requester will see this.",
    "Returned", "What needs to change?",
    "Optional comment for the requester")
lblCommentError.Visible : locDecision <> "Approved" && Len(Trim(txtComment.Text)) < 10 && locTriedSave

// Save decision
UpdateContext({ locTriedSave: true });
With(
    { current: LookUp(Requests, ID = varRecord.ID) },
    If(
        Lower(current.Manager.Email) <> Lower(User().Email),
        Notify("Only the assigned manager can decide this request.", NotificationType.Error),
        current.Status.Value <> "Awaiting manager",
        Notify("This request is no longer awaiting a decision.", NotificationType.Warning),
        locDecision <> "Approved" && Len(Trim(txtComment.Text)) < 10,
        Notify("Add a short explanation for the requester.", NotificationType.Error),
        IfError(
            Set(varRecord,
                Patch(Requests, current, {
                    Status:            { Value: locDecision },
                    ManagerComment:    Trim(txtComment.Text),
                    ManagerDecisionOn: Now()
                })
            );
            Reset(txtComment); UpdateContext({ locDecision: Blank(), locTriedSave: false });
            Notify("Decision saved. The requester will be notified.", NotificationType.Success),
            Notify("Could not save: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// Requester's view
lblDecision.Text : varRecord.Status.Value & " by " & varRecord.Manager.DisplayName & " on " & Text(varRecord.ManagerDecisionOn, "d mmm yyyy")
lblComment.Text  : Coalesce(varRecord.ManagerComment, "No comment was added.")

patch-a-conditional-required-field-set.formulaOrCode:
// One place for the rules (App.Formulas or screen-level)
// Which fields each request type needs
nfRules = Table(
    { Type: "Purchase", Field: "CostCentre" },
    { Type: "Purchase", Field: "Supplier" },
    { Type: "Travel",   Field: "Destination" },
    { Type: "Travel",   Field: "TravelDates" },
    { Type: "Access",   Field: "SystemName" }
);

// Is a field needed right now?
// conCostCentre.Visible
"CostCentre" in Filter(nfRules, Type = ddType.Selected.Value).Field
// Justification is needed above a threshold
conJustification.Visible : Value(txtAmount.Text) > 5000

// Save
ClearCollect(
    colMissing,
    Filter(
        Table(
            { Field: "CostCentre",    Empty: IsBlank(Trim(txtCostCentre.Text)),  Label: "Cost centre" },
            { Field: "Supplier",      Empty: IsBlank(Trim(txtSupplier.Text)),    Label: "Supplier" },
            { Field: "Destination",   Empty: IsBlank(Trim(txtDestination.Text)), Label: "Destination" },
            { Field: "TravelDates",   Empty: IsBlank(dpFrom.SelectedDate) || IsBlank(dpTo.SelectedDate), Label: "Travel dates" },
            { Field: "SystemName",    Empty: IsBlank(ddSystem.Selected.Value),   Label: "System" }
        ),
        Empty && Field in Filter(nfRules, Type = ddType.Selected.Value).Field
    )
);
If(Value(txtAmount.Text) > 5000 && IsBlank(Trim(txtJustification.Text)),
   Collect(colMissing, { Field: "Justification", Empty: true, Label: "Justification (amounts over 5,000)" }));

If(
    !IsEmpty(colMissing),
    Notify("Complete: " & Concat(colMissing, Label, ", "), NotificationType.Error),
    With(
        { t: ddType.Selected.Value },
        Patch(Requests, Coalesce(varRecord, Defaults(Requests)), {
            RequestType:   ddType.Selected,
            Amount:        Value(txtAmount.Text),
            // save a value only when the field applies, otherwise clear it
            CostCentre:    If(t = "Purchase", Trim(txtCostCentre.Text), Blank()),
            Supplier:      If(t = "Purchase", Trim(txtSupplier.Text), Blank()),
            Destination:   If(t = "Travel", Trim(txtDestination.Text), Blank()),
            TravelFrom:    If(t = "Travel", dpFrom.SelectedDate, Blank()),
            TravelTo:      If(t = "Travel", dpTo.SelectedDate, Blank()),
            SystemName:    If(t = "Access", ddSystem.Selected.Value, Blank()),
            Justification: If(Value(txtAmount.Text) > 5000, Trim(txtJustification.Text), Blank())
        })
    )
)

patch-a-related-document-link-field.formulaOrCode:
Columns: DocumentLink (Hyperlink) | DocumentTitle (Single line of text)

// Save
With(
    { url: Trim(txtLink.Text) },
    If(
        IsBlank(url),
        Patch(Requests, varRecord, { DocumentLink: Blank(), DocumentTitle: Blank() }),

        !IsMatch(url, "^https://[^\s]+$", MatchOptions.IgnoreCase),
        Notify("Enter a full web address that starts with https://", NotificationType.Error),

        Len(url) > 255,
        Notify("That link is too long for the list. Use the document's short Copy link address.", NotificationType.Error),

        IfError(
            Set(varRecord,
                Patch(Requests, varRecord, {
                    DocumentLink:  url,
                    DocumentTitle: Coalesce(Trim(txtLinkTitle.Text), "Related document")
                })
            );
            Notify("Link saved", NotificationType.Success),
            Notify("Could not save the link: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// Open
btnOpen.Visible  : !IsBlank(varRecord.DocumentLink)
btnOpen.Text     : Coalesce(varRecord.DocumentTitle, "Open document")
btnOpen.OnSelect : Launch(varRecord.DocumentLink, {}, LaunchTarget.New)

// Pick a file from a library instead of pasting (gallery on the library)
galDocs.Items    : Filter('Project Documents', StartsWith(Name, txtFind.Text))
galDocs.OnSelect : UpdateContext({ locPickedUrl: ThisItem.'Link to item', locPickedName: ThisItem.Name })

// Restrict to your tenant
StartsWith(Lower(url), "https://contoso.sharepoint.com/")

// HTML link in an HTML text control
"<a href='" & varRecord.DocumentLink & "' target='_blank'>" & EncodeHTML(varRecord.DocumentTitle) & "</a>"

patch-a-training-completion-acknowledgem.formulaOrCode:
Lists
  Policies         : Title | Version (Text) | DocumentLink | RequiredFor (Choice) | DueDate
  Acknowledgements : Title | PolicyId (Number, indexed) | PolicyVersion | UserEmail (Text, indexed)
                     UserName | AcknowledgedOn | Statement (Multi-line)

// Has the user already acknowledged this version?
UpdateContext({
    locExisting: LookUp(Acknowledgements,
        PolicyId = varPolicy.ID && UserEmail = gblUserEmail && PolicyVersion = varPolicy.Version)
})

// Controls
btnOpenPolicy.OnSelect : Launch(varPolicy.DocumentLink); UpdateContext({ locOpened: true })
chkAgree.Text          : "I have read and understood " & varPolicy.Title & " (version " & varPolicy.Version & ")"
chkAgree.DisplayMode   : If(locOpened && IsBlank(locExisting), DisplayMode.Edit, DisplayMode.Disabled)
btnConfirm.DisplayMode : If(chkAgree.Value && IsBlank(locExisting), DisplayMode.Edit, DisplayMode.Disabled)

// Confirm
If(
    !IsBlank(LookUp(Acknowledgements, PolicyId = varPolicy.ID && UserEmail = gblUserEmail && PolicyVersion = varPolicy.Version)),
    Notify("You have already acknowledged this version.", NotificationType.Information),
    IfError(
        UpdateContext({
            locExisting: Patch(Acknowledgements, Defaults(Acknowledgements), {
                Title:          varPolicy.Title & " v" & varPolicy.Version & " - " & User().FullName,
                PolicyId:       varPolicy.ID,
                PolicyVersion:  varPolicy.Version,
                UserEmail:      gblUserEmail,
                UserName:       User().FullName,
                AcknowledgedOn: Now(),
                Statement:      chkAgree.Text
            })
        });
        Notify("Thank you. Your acknowledgement has been recorded.", NotificationType.Success),
        Notify("Could not record your acknowledgement: " & FirstError.Message, NotificationType.Error)
    )
)

// Status for the user
lblStatus.Text : If(IsBlank(locExisting), "Not yet acknowledged",
                    "Acknowledged on " & Text(locExisting.AcknowledgedOn, "d mmm yyyy hh:mm"))

// My outstanding policies
Filter(colPolicies, !(ID in Filter(Acknowledgements, UserEmail = gblUserEmail).PolicyId))

patch-a-pmo-triage-assignment.formulaOrCode:
Columns: Status | Category | Priority | AssignedTo (Person) | DueDate | TriagedBy (Text) | TriagedOn | TriageNote

// Queue
galNew.Items : SortByColumns(Filter(Requests, Status.Value = "New"), "Created", SortOrder.Ascending)
lblAge.Text  : DateDiff(ThisItem.Created, Now(), TimeUnit.Hours) & " h waiting"

// Suggest an assignee from a routing list (cached): Category -> DefaultOwnerEmail
cmbAssignee.DefaultSelectedItems :
    With({ owner: LookUp(colRouting, Category = ddCategory.Selected.Value).DefaultOwnerEmail },
         If(IsBlank(owner), Blank(), Office365Users.SearchUserV2({ searchTerm: owner, top: 1 }).value))

// Suggested due date from priority
dpDue.DefaultDate : DateAdd(Today(), Switch(ddPriority.Selected.Value, "Urgent", 1, "High", 3, "Normal", 7, 14), TimeUnit.Days)

// Assign button OnSelect
With(
    { current: LookUp(Requests, ID = galNew.Selected.ID) },
    If(
        current.Status.Value <> "New",
        Notify("Already triaged by " & current.TriagedBy, NotificationType.Warning); Refresh(Requests),
        IsBlank(cmbAssignee.Selected.Mail) || IsBlank(ddCategory.Selected.Value),
        Notify("Choose a category and an assignee", NotificationType.Error),
        IfError(
            Patch(Requests, current, {
                Status:    { Value: "Assigned" },
                Category:  { Value: ddCategory.Selected.Value },
                Priority:  { Value: ddPriority.Selected.Value },
                DueDate:   dpDue.SelectedDate,
                AssignedTo: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                    Claims: "i:0#.f|membership|" & Lower(cmbAssignee.Selected.Mail),
                    DisplayName: cmbAssignee.Selected.DisplayName,
                    Email: cmbAssignee.Selected.Mail,
                    Department: "", JobTitle: "", Picture: ""
                },
                TriagedBy:  User().Email,
                TriagedOn:  Now(),
                TriageNote: Trim(txtNote.Text)
            });
            Reset(cmbAssignee); Reset(txtNote);
            Notify("Assigned to " & cmbAssignee.Selected.DisplayName, NotificationType.Success),
            Notify("Could not assign: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// Workload hint beside the assignee
"Open items: " & CountRows(Filter(colOpen, AssignedTo.Email = cmbAssignee.Selected.Mail))

build-a-tabbed-request-detail-screen.formulaOrCode:
// Screen.OnVisible
UpdateContext({ locTab: Coalesce(locTab, "Details") })

// Tab bar (horizontal gallery, galTabs)
Items :
    Table(
        { Key: "Details",  Label: "Details" },
        { Key: "Activity", Label: "Activity (" & CountRows(colActivity) & ")" },
        { Key: "Files",    Label: "Files (" & CountRows(varRecord.Attachments) & ")" },
        { Key: "Approval", Label: "Approval" }
    )
// Hide a tab for some users: wrap in Filter(..., Key <> "Approval" || nfIsApprover)

// Inside the tab template
lblTab.Text        : ThisItem.Label
lblTab.FontWeight  : If(ThisItem.Key = locTab, FontWeight.Semibold, FontWeight.Normal)
recUnderline.Visible: ThisItem.Key = locTab
galTabs.OnSelect   : UpdateContext({ locTab: ThisItem.Key })

// Content containers (same position, same size)
conDetails.Visible  : locTab = "Details"
conActivity.Visible : locTab = "Activity"
conFiles.Visible    : locTab = "Files"
conApproval.Visible : locTab = "Approval"

// Load a tab's data only when it is first opened
galTabs.OnSelect :
    UpdateContext({ locTab: ThisItem.Key });
    If(ThisItem.Key = "Activity" && IsEmpty(colActivity),
       ClearCollect(colActivity, Filter('Request History', RequestId = varRecord.ID)))

// Show an error dot on a tab that has invalid inputs
icoTabError.Visible : ThisItem.Key in colErrors.Tab

// Open the screen on a chosen tab
Navigate(scrDetail, ScreenTransition.None, { locTab: "Approval" })

// Keep one Save button outside the containers so it saves fields from every tab.
// Modern alternative: the Tab list control, with OnSelect : UpdateContext({ locTab: Self.Selected.Key })

build-a-compact-mobile-request-form.formulaOrCode:
Layout (responsive app, or a phone-format app)
  Screen
   ├─ conHeader        fixed height 56
   ├─ conBody          vertical container, LayoutOverflowY: Scroll, Gap 12, Padding 16
   │     each field  = label + input, input Height 48, AlignInContainer: Stretch
   └─ conFooter        fixed height 72, Submit button full width

// Body height when not using auto layout
conBody.Height : Parent.Height - conHeader.Height - conFooter.Height

// Inputs
txtQty.Format            : TextFormat.Number               // numeric keyboard
txtQty.VirtualKeyboardMode: VirtualKeyboardMode.Numeric
txtEmail.VirtualKeyboardMode: VirtualKeyboardMode.Text
txtNotes.Mode            : TextMode.MultiLine              // Height 96
dpNeeded.DefaultDate     : Today()

// Fewer taps: buttons instead of a dropdown for 2 to 4 options
galPriority.Items    : ["Low", "Normal", "High"]
galPriority.OnSelect : UpdateContext({ locPriority: ThisItem.Value })
btnOption.Fill       : If(ThisItem.Value = locPriority, nfTheme.Primary, Color.White)

// Sensible defaults so most fields need no input
Screen.OnVisible : UpdateContext({ locPriority: "Normal" })
lblSite.Text     : "Site: " & Coalesce(gblLastSite, "Not set")

// Photo
btnPhoto : Add picture control, or a Camera control with StreamRate 100

// Submit
btnSubmit.DisplayMode : If(IsBlank(Trim(txtTitle.Text)) || locBusy, DisplayMode.Disabled, DisplayMode.Edit)
btnSubmit.OnSelect :
    UpdateContext({ locBusy: true });
    IfError(
        Patch(Requests, Defaults(Requests), {
            Title: Trim(txtTitle.Text),
            Quantity: Value(txtQty.Text),
            Priority: { Value: locPriority },
            NeededBy: dpNeeded.SelectedDate,
            Notes: txtNotes.Text
        });
        Set(gblLastSite, ddSite.Selected.Value);
        Reset(txtTitle); Reset(txtQty); Reset(txtNotes);
        Notify("Request sent", NotificationType.Success),
        Notify("Not sent: " & FirstError.Message, NotificationType.Error)
    );
    UpdateContext({ locBusy: false })

// Small screens
lblHint.Visible : App.ActiveScreen.Size <= ScreenSize.Small

build-a-reusable-filter-panel.formulaOrCode:
// State
Screen.OnVisible :
    If(IsBlank(locFilters),
       UpdateContext({ locFilters: { Status: "All", Owner: "Anyone", From: Blank(), To: Blank() }, locPanel: false }))

// Open / close
icoFilter.OnSelect : UpdateContext({ locPanel: true })
conPanel.Visible   : locPanel
conPanel.X         : Parent.Width - Self.Width             // right-hand side
recScrim.OnSelect  : UpdateContext({ locPanel: false })

// Controls in the panel (their defaults come from the applied filters)
ddStatus.Items   : ["All", "New", "In progress", "Waiting", "Closed"]     Default : locFilters.Status
ddOwner.Items    : ["Anyone", "Me", "Unassigned"]                         Default : locFilters.Owner
dpFrom.DefaultDate : locFilters.From                                      dpTo.DefaultDate : locFilters.To

// Apply
btnApply.OnSelect :
    UpdateContext({
        locFilters: { Status: ddStatus.Selected.Value, Owner: ddOwner.Selected.Value,
                      From: dpFrom.SelectedDate, To: dpTo.SelectedDate },
        locPanel: false
    })

// Clear all
btnClear.OnSelect :
    UpdateContext({ locFilters: { Status: "All", Owner: "Anyone", From: Blank(), To: Blank() } });
    Reset(ddStatus); Reset(ddOwner); Reset(dpFrom); Reset(dpTo)

// Gallery Items (every condition is delegable in SharePoint)
SortByColumns(
    Filter(
        Requests,
        locFilters.Status = "All" || Status.Value = locFilters.Status,
        locFilters.Owner = "Anyone"
            || (locFilters.Owner = "Me" && AssignedTo.Email = gblUserEmail)
            || (locFilters.Owner = "Unassigned" && AssignedTo.Email = Blank()),
        IsBlank(locFilters.From) || Created >= locFilters.From,
        IsBlank(locFilters.To)   || Created < DateAdd(locFilters.To, 1, TimeUnit.Days),
        StartsWith(Title, txtSearch.Text)
    ),
    "Created", SortOrder.Descending
)

// Active filter count on the icon
lblBadge.Text :
    If(locFilters.Status <> "All", 1, 0) + If(locFilters.Owner <> "Anyone", 1, 0) +
    If(!IsBlank(locFilters.From), 1, 0) + If(!IsBlank(locFilters.To), 1, 0)
lblBadge.Visible : Value(Self.Text) > 0

// Reuse: turn the panel into a component with an output property Filters (record)
// and an OnApply behaviour property.

build-a-multi-step-intake-wizard.formulaOrCode:
// Steps (App.Formulas or screen-level)
nfSteps = Table(
    { No: 1, Title: "About you" },
    { No: 2, Title: "Request details" },
    { No: 3, Title: "Costs" },
    { No: 4, Title: "Review" }
);
Screen.OnVisible : UpdateContext({ locStep: 1 })

// Step containers
conStep1.Visible : locStep = 1     conStep2.Visible : locStep = 2     ...

// Progress indicator (horizontal gallery on nfSteps)
cirStep.Fill   : If(ThisItem.No < locStep, RGBA(16, 124, 16, 1), ThisItem.No = locStep, nfTheme.Primary, RGBA(200, 198, 196, 1))
lblStep.Text   : If(ThisItem.No < locStep, "✓", ThisItem.No)
lblHeading.Text: "Step " & locStep & " of " & CountRows(nfSteps) & ": " & LookUp(nfSteps, No = locStep).Title

// Per-step validation
// lblStepError holds the first problem for the current step
Switch(
    locStep,
    1, If(IsBlank(cmbRequester.Selected), "Choose who the request is for"),
    2, If(IsBlank(Trim(txtTitle.Text)), "Enter a title",
          IsBlank(ddCategory.Selected.Value), "Choose a category",
          IsBlank(dpNeeded.SelectedDate), "Choose when this is needed"),
    3, If(!IsNumeric(txtAmount.Text), "Enter the estimated cost as a number",
          Value(txtAmount.Text) > 5000 && IsBlank(Trim(txtJustification.Text)), "Add a justification for amounts over 5,000")
)

// Next / Back
btnNext.OnSelect :
    If(IsBlank(lblStepError.Text),
       UpdateContext({ locStep: locStep + 1, locShowError: false }),
       UpdateContext({ locShowError: true }))
btnNext.Visible  : locStep < CountRows(nfSteps)
btnBack.OnSelect : UpdateContext({ locStep: locStep - 1, locShowError: false })
btnBack.Visible  : locStep > 1
lblStepError.Visible : locShowError && !IsBlank(lblStepError.Text)

// Skip a step that does not apply
// replace locStep + 1 with: locStep + If(locStep = 2 && ddCategory.Selected.Value = "Advice", 2, 1)

// Review step: read-only summary with Edit links
lnkEdit2.OnSelect : UpdateContext({ locStep: 2 })

// Submit (last step)
btnSubmit.Visible  : locStep = CountRows(nfSteps)
btnSubmit.OnSelect :
    IfError(
        Patch(Requests, Defaults(Requests), {
            Title: Trim(txtTitle.Text), Category: { Value: ddCategory.Selected.Value },
            NeededBy: dpNeeded.SelectedDate, Amount: Value(txtAmount.Text), Justification: txtJustification.Text
        });
        Navigate(scrThanks),
        Notify("Could not submit: " & FirstError.Message, NotificationType.Error)
    )

build-a-collection-backed-review-screen.formulaOrCode:
// Add a line
If(
    IsBlank(Trim(txtItem.Text)) || !IsNumeric(txtQty.Text) || !IsNumeric(txtPrice.Text),
    Notify("Enter an item, a quantity and a price", NotificationType.Error),
    Collect(colLines, {
        LineId: GUID(),
        Item: Trim(txtItem.Text),
        Qty: Value(txtQty.Text),
        UnitPrice: Value(txtPrice.Text)
    });
    Reset(txtItem); Reset(txtQty); Reset(txtPrice); SetFocus(txtItem)
)

// Review gallery
galLines.Items    : colLines
lblLineTotal.Text : Text(ThisItem.Qty * ThisItem.UnitPrice, "$#,##0.00")

// Edit a quantity in the row (text input OnChange)
Patch(colLines, ThisItem, { Qty: Value(Self.Text) })

// Remove a row
icoRemove.OnSelect : Remove(colLines, ThisItem)

// Totals
lblCount.Text : CountRows(colLines) & " lines"
lblTotal.Text : Text(Sum(colLines, Qty * UnitPrice), "$#,##0.00")

// Save everything
btnSave.DisplayMode : If(IsEmpty(colLines) || locBusy, DisplayMode.Disabled, DisplayMode.Edit)
btnSave.OnSelect :
    UpdateContext({ locBusy: true });
    IfError(
        // 1. header
        Set(varOrder, Patch(Orders, Defaults(Orders), {
            Title: txtOrderTitle.Text,
            Total: Sum(colLines, Qty * UnitPrice)
        }));
        // 2. lines in one call
        Patch(
            'Order Lines',
            ForAll(colLines As L, {
                Title: L.Item, OrderId: varOrder.ID, Quantity: L.Qty, UnitPrice: L.UnitPrice
            })
        );
        Clear(colLines);
        Notify("Order " & varOrder.ID & " saved", NotificationType.Success);
        Navigate(scrOrders),
        Notify("Save failed: " & FirstError.Message & " Your lines are still on this screen.", NotificationType.Error)
    );
    UpdateContext({ locBusy: false })

// Editing an existing order: load its lines first
ClearCollect(colLines,
    ForAll(Filter('Order Lines', OrderId = varOrder.ID) As R,
           { LineId: GUID(), SpId: R.ID, Item: R.Title, Qty: R.Quantity, UnitPrice: R.UnitPrice }))

// Discard
btnDiscard.OnSelect : Clear(colLines); Back()

build-a-requester-self-service-screen.formulaOrCode:
// My requests, with the action expected of me first
ClearCollect(
    colMine,
    AddColumns(
        Filter(Requests, Author.Email = gblUserEmail),
        NeedsMe, Status.Value in ["Returned", "Awaiting your confirmation"]
    )
);
galMine.Items : SortByColumns(colMine, "NeedsMe", SortOrder.Descending, "Modified", SortOrder.Descending)

// Banner on rows that need the requester
lblAction.Visible : ThisItem.NeedsMe
lblAction.Text    : Switch(ThisItem.Status.Value,
                        "Returned", "More information needed: " & ThisItem.ReturnReason,
                        "Awaiting your confirmation", "Please confirm this has been completed")

// Actions on the detail panel, shown only when valid
btnAddInfo.Visible  : varRecord.Status.Value = "Returned"
btnWithdraw.Visible : varRecord.Status.Value in ["Submitted", "Returned", "Awaiting approval"]
btnConfirm.Visible  : varRecord.Status.Value = "Awaiting your confirmation"
btnReopen.Visible   : varRecord.Status.Value = "Closed" && DateDiff(varRecord.ClosedOn, Now(), TimeUnit.Days) <= 14

// Add information and resubmit
If(
    IsBlank(Trim(txtMoreInfo.Text)),
    Notify("Add the information that was asked for", NotificationType.Error),
    Set(varRecord,
        Patch(Requests, LookUp(Requests, ID = varRecord.ID), {
            Status: { Value: "Submitted" },
            RequesterNotes: Text(Now(), "d mmm yyyy hh:mm") & ": " & Trim(txtMoreInfo.Text) &
                            If(!IsBlank(varRecord.RequesterNotes), Char(10) & varRecord.RequesterNotes)
        }));
    Notify("Thanks. Your request is back with the team.", NotificationType.Success)
)

// Confirm completion
Set(varRecord, Patch(Requests, LookUp(Requests, ID = varRecord.ID), {
    Status: { Value: "Closed" }, ClosedOn: Now(), ConfirmedByRequester: true,
    SatisfactionScore: ratScore.Value
}))

// Withdraw
Set(varRecord, Patch(Requests, LookUp(Requests, ID = varRecord.ID), {
    Status: { Value: "Cancelled" }, CancelledOn: Now(), CancelNote: "Withdrawn by requester: " & txtWhy.Text
}))

// Where things stand, in plain words
lblWhere.Text : Switch(varRecord.Status.Value,
    "Submitted", "Waiting to be picked up by the team.",
    "In progress", "Being worked on by " & varRecord.AssignedTo.DisplayName & ".",
    "Awaiting approval", "Waiting for approval from " & varRecord.Approver.DisplayName & ".",
    varRecord.Status.Value)

build-an-admin-data-repair-screen.formulaOrCode:
// Screen guard
Screen.OnVisible : If(!nfIsAdmin, Navigate(scrHome))

// Checks
ddCheck.Items : ["Open items with no owner", "Closed items with no closed date", "Items past due and still New", "Child rows with no parent"]

// Preview (button "Find")
Switch(
    ddCheck.Selected.Value,
    "Open items with no owner",
        ClearCollect(colRepair, Filter(Requests, Status.Value = "In progress" && AssignedTo.Email = Blank())),
    "Closed items with no closed date",
        ClearCollect(colRepair, Filter(Requests, Status.Value = "Closed" && ClosedOn = Blank())),
    "Items past due and still New",
        ClearCollect(colRepair, Filter(Requests, Status.Value = "New" && DueDate < Today())),
    "Child rows with no parent",
        ClearCollect(colRepair, Filter('Request Tasks', !(RequestId in ShowColumns(colAllRequests, ID).ID)))
);
UpdateContext({ locChecked: ddCheck.Selected.Value })

lblFound.Text   : CountRows(colRepair) & " records found"
galRepair.Items : colRepair                   // review before fixing; a checkbox per row can exclude rows

// Fix (button enabled only after a preview of the same check)
btnFix.DisplayMode : If(locChecked = ddCheck.Selected.Value && !IsEmpty(colRepair), DisplayMode.Edit, DisplayMode.Disabled)
btnFix.OnSelect :
    UpdateContext({ locBusy: true });
    IfError(
        Switch(
            locChecked,
            "Closed items with no closed date",
                Patch(Requests, ForAll(colRepair As R, { ID: R.ID, ClosedOn: R.Modified })),
            "Items past due and still New",
                Patch(Requests, ForAll(colRepair As R, { ID: R.ID, Status: { Value: "Overdue" } })),
            "Open items with no owner",
                Patch(Requests, ForAll(colRepair As R, { ID: R.ID, Status: { Value: "New" } }))
        );
        Patch('Admin Log', Defaults('Admin Log'), {
            Title: locChecked,
            RecordCount: CountRows(colRepair),
            RecordIds: Concat(colRepair, Text(ID), ","),
            RunBy: User().Email,
            RunOn: Now()
        });
        Notify(CountRows(colRepair) & " records fixed", NotificationType.Success);
        Clear(colRepair),
        Notify("Repair stopped: " & FirstError.Message, NotificationType.Error)
    );
    UpdateContext({ locBusy: false })

build-a-printable-request-summary.formulaOrCode:
// A dedicated screen: scrPrint, white background, sized like a page
// Screen width 794, height 1123 (A4 at 96 dpi) or a container with those dimensions

// Open it
btnPrintView.OnSelect : Navigate(scrPrint, ScreenTransition.None, { locRecord: varRecord })

// Layout: header with logo and reference, a two-column grid of label and value, then sections
lblRef.Text      : "Request " & locRecord.RequestNumber
lblPrinted.Text  : "Printed " & Text(Now(), "d mmm yyyy hh:mm") & " by " & User().FullName
lblStatus.Text   : locRecord.Status.Value
lblRequester.Text: locRecord.Author.DisplayName
lblNeeded.Text   : Text(locRecord.NeededBy, "d mmm yyyy")
lblAmount.Text   : Text(locRecord.Amount, "$#,##0.00")
htmlDetails.HtmlText : locRecord.Details             // auto height on

// Line items as HTML so the table can grow
htmlLines.HtmlText :
    "<table width='100%' style='border-collapse:collapse'>" &
    "<tr><th align='left'>Item</th><th align='right'>Qty</th><th align='right'>Price</th></tr>" &
    Concat(colLines,
        "<tr><td>" & EncodeHTML(Title) & "</td><td align='right'>" & Quantity &
        "</td><td align='right'>" & Text(UnitPrice, "#,##0.00") & "</td></tr>") &
    "</table>"

// Print: buttons hide themselves while printing
btnPrint.OnSelect : Print()
btnPrint.Visible  : !scrPrint.Printing
btnBack.Visible   : !scrPrint.Printing

// Save as PDF to SharePoint through a flow
With(
    { file: PDF(scrPrint, { Size: PaperSize.A4, Orientation: PaperOrientation.Portrait, Margin: "12mm", ExpandContainers: true }) },
    SaveRequestPdf.Run(
        "Request-" & locRecord.RequestNumber & ".pdf",
        { file: { name: "Request-" & locRecord.RequestNumber & ".pdf", contentBytes: file } }
    )
);
Notify("PDF saved to the request's folder", NotificationType.Success)

// Flow: Power Apps (V2) trigger with a text input and a file input -> Create file in a document library

// Preview the PDF in the app
pdfViewer.Document : PDF(conPrintArea)

use-a-loading-state-for-flow-calls.formulaOrCode:
// Button OnSelect
UpdateContext({ locBusy: true, locBusyText: "Submitting for approval..." });
IfError(
    UpdateContext({
        locResult: SubmitForApproval.Run(varRecord.ID, Trim(txtNote.Text))
    });
    If(
        locResult.success = "true",
        Notify("Sent to " & locResult.approvername, NotificationType.Success);
        Set(varRecord, LookUp(Requests, ID = varRecord.ID)),      // pick up changes the flow made
        Notify("The flow reported a problem: " & locResult.message, NotificationType.Error)
    ),
    Notify(
        If("timeout" in Lower(FirstError.Message) || "GatewayTimeout" in FirstError.Message,
           "This is taking longer than expected. Check the request again in a minute before retrying.",
           "Could not start the approval: " & FirstError.Message),
        NotificationType.Error
    )
);
UpdateContext({ locBusy: false })

// Overlay and button state
conBusy.Visible       : locBusy
lblBusy.Text          : locBusyText
btnSubmit.DisplayMode : If(locBusy || varRecord.Status.Value <> "Draft", DisplayMode.Disabled, DisplayMode.Edit)

// Flow design
//  Trigger : Power Apps (V2) with inputs RequestId (Number), Note (Text)
//  ... actions ...
//  Respond to a Power App or flow: success (Text) = true, approvername (Text), message (Text)
//  Put the main actions in a Scope; add a second Respond with success = false that runs after the scope has failed.

// Long-running alternative
//  1. Flow responds immediately after setting Status = "Processing"
//  2. App shows "Processing" and checks again with a Timer:
tmrPoll.Duration : 5000   Repeat : true   Start : varRecord.Status.Value = "Processing"
tmrPoll.OnTimerEnd : Set(varRecord, LookUp(Requests, ID = varRecord.ID))

use-a-save-result-variable-for-navigatio.formulaOrCode:
// Custom form
IfError(
    Set(varSaved,
        Patch(Requests, Coalesce(varRecord, Defaults(Requests)), {
            Title: Trim(txtTitle.Text),
            Category: { Value: ddCategory.Selected.Value }
        })
    );
    Notify("Saved", NotificationType.Success);
    Navigate(scrDetail, ScreenTransition.None, { locRecord: varSaved, locMode: "View" }),

    // failure: stay on this screen
    Notify("Not saved: " & FirstError.Message, NotificationType.Error)
)

// Without IfError: check the data source's errors
Set(varSaved, Patch(Requests, Defaults(Requests), { Title: txtTitle.Text }));
If(
    IsEmpty(Errors(Requests, varSaved)),
    Navigate(scrDetail, ScreenTransition.None, { locRecord: varSaved }),
    Notify(First(Errors(Requests, varSaved)).Message, NotificationType.Error)
)

// Edit form: never navigate from the button
btnSave.OnSelect     : SubmitForm(frmRequest)
frmRequest.OnSuccess : Set(varSaved, frmRequest.LastSubmit);
                       Navigate(scrDetail, ScreenTransition.None, { locRecord: varSaved })
frmRequest.OnFailure : Notify(frmRequest.Error, NotificationType.Error)

// Choose the destination from the result
If(
    varSaved.Status.Value = "Draft", Navigate(scrMyDrafts),
    varSaved.NeedsApproval,          Navigate(scrSubmitted),
    Navigate(scrDetail, ScreenTransition.None, { locRecord: varSaved })
)

// Bulk save: move on only if every row was written
With(
    { result: Patch('Order Lines', colNewLines) },
    If(CountRows(result) = CountRows(colNewLines), Navigate(scrDone),
       Notify("Some lines were not saved. Try again.", NotificationType.Error))
)

// The new ID is available straight away
lblConfirm.Text : "Your reference is " & varSaved.ID

use-app-settings-for-feature-flags.formulaOrCode:
List: Feature Flags
  Title (flag name, unique) | Enabled (Yes/No) | PilotUsers (Multiple lines: emails separated by ;)
  Description | Owner | RemoveAfter (Date)

  BulkUpload      | No  | ana@contoso.com;raj@contoso.com
  NewDashboard    | Yes |
  ExportToExcel   | No  |

// App.OnStart
ClearCollect(colFlags, ShowColumns('Feature Flags', Title, Enabled, PilotUsers));

// App.Formulas: one helper per flag
nfUserEmail = Lower(User().Email);

nfFlagBulkUpload =
    With({ f: LookUp(colFlags, Title = "BulkUpload") },
         Coalesce(f.Enabled, false) || nfUserEmail in Split(Lower(Substitute(Coalesce(f.PilotUsers, ""), " ", "")), ";").Value);

nfFlagNewDashboard =
    With({ f: LookUp(colFlags, Title = "NewDashboard") },
         Coalesce(f.Enabled, false) || nfUserEmail in Split(Lower(Substitute(Coalesce(f.PilotUsers, ""), " ", "")), ";").Value);

// With user-defined functions enabled, one function covers every flag
fnFlag(name: Text): Boolean =
    With({ f: LookUp(colFlags, Title = name) },
         Coalesce(f.Enabled, false) || nfUserEmail in Split(Lower(Substitute(Coalesce(f.PilotUsers, ""), " ", "")), ";").Value);

// Usage
btnBulkUpload.Visible : nfFlagBulkUpload
App.StartScreen       : If(nfFlagNewDashboard, scrDashboardV2, scrDashboard)
If(fnFlag("ExportToExcel"), ExportFlow.Run(), Notify("Export is not available yet"))

// A missing flag is treated as off, so a new build is safe before its flag row exists.

// Housekeeping view in SharePoint: flags where Enabled = Yes and RemoveAfter < today

use-a-local-collection-for-draft-attachm.formulaOrCode:
// Option A: keep the attachment control from a form, save with Patch
// Add an Edit form (frmFiles) with only the Attachments card, DefaultMode New. Hide everything else.
// Save:
Set(varSaved,
    Patch(
        Requests,
        Defaults(Requests),
        { Title: txtTitle.Text, Details: txtDetails.Text },
        frmFiles.Updates                    // brings the attachments along
    )
)

// Option B: your own collection (works for photos and for library uploads)
// Attachment control (taken from a form) OnAddFile:
ClearCollect(colFiles,
    ForAll(attFiles.Attachments As A, { Name: A.Name, Content: A.Value }))
// Camera
camPhoto.OnSelect :
    Collect(colFiles, { Name: "Photo-" & Text(Now(), "yyyymmdd-hhmmss") & ".jpg", Content: camPhoto.Photo })

// List and remove
galFiles.Items     : colFiles
icoRemove.OnSelect : Remove(colFiles, ThisItem)

// Limits
If(CountRows(colFiles) > 5, Notify("Attach up to 5 files", NotificationType.Warning))

// Submit: create the item, then upload each file with a flow
Set(varSaved, Patch(Requests, Defaults(Requests), { Title: txtTitle.Text }));
ForAll(
    colFiles As F,
    UploadAttachment.Run(
        varSaved.ID,
        { file: { name: F.Name, contentBytes: F.Content } }
    )
);
Notify("Request and " & CountRows(colFiles) & " files saved", NotificationType.Success);
Clear(colFiles)

// Flow "UploadAttachment": Power Apps (V2) trigger with ItemId (Number) and File (File)
//   SharePoint - Add attachment: Id = ItemId, File Name = triggerBody()?['file']?['name'],
//                                File Content = triggerBody()?['file']?['contentBytes']
//   For a library: Create file in /Requests/<ItemId>/

// Show saved attachments later
galSaved.Items : varSaved.Attachments           // DisplayName, AbsoluteUri
Launch(ThisItem.AbsoluteUri)

use-clear-button-states-for-approvals.formulaOrCode:
// Work out what the user can do, once (screen-level With, hidden labels, or named formulas)
// locCan record set in OnVisible and after each save:
UpdateContext({
    locCan: With(
        {
            isApprover:  Lower(varRecord.Approver.Email) = Lower(User().Email),
            isRequester: Lower(varRecord.Author.Email) = Lower(User().Email),
            status:      varRecord.Status.Value
        },
        {
            Approve:  isApprover && status = "Awaiting approval" && !isRequester,
            Reject:   isApprover && status = "Awaiting approval",
            Withdraw: isRequester && status in ["Submitted", "Awaiting approval"],
            Edit:     isRequester && status in ["Draft", "Returned"],
            Reason:   If(
                          status in ["Approved", "Rejected"], "This request was " & Lower(status) & " on " & Text(varRecord.DecisionOn, "d mmm yyyy") & ".",
                          status = "Awaiting approval" && !isApprover, "Waiting for " & varRecord.Approver.DisplayName & " to decide.",
                          isApprover && isRequester, "You cannot approve your own request.",
                          ""
                      )
        }
    )
})

// Buttons
btnApprove.Visible     : varRecord.Status.Value = "Awaiting approval" && (locCan.Approve || locCan.Reject)
btnApprove.DisplayMode : If(locCan.Approve && !locBusy, DisplayMode.Edit, DisplayMode.Disabled)
btnReject.DisplayMode  : If(locCan.Reject && !locBusy, DisplayMode.Edit, DisplayMode.Disabled)
btnWithdraw.Visible    : locCan.Withdraw
btnEdit.Visible        : locCan.Edit

// Explain
lblReason.Text    : locCan.Reason
lblReason.Visible : !IsBlank(locCan.Reason)

// Visual hierarchy
btnApprove : primary colour, on the right
btnReject  : outline style, to its left
// Destructive or irreversible actions open a confirmation dialog first.

// While saving
btnApprove.Text : If(locBusy && locAction = "Approve", "Approving...", "Approve")

// Check again at the moment of action (the record may have changed)
With({ current: LookUp(Requests, ID = varRecord.ID) },
     If(current.Status.Value <> "Awaiting approval",
        Notify("This request has already been decided.", NotificationType.Warning); Set(varRecord, current),
        Select(btnDoApprove)))            // hidden button that holds the approval Patch

use-fallback-text-for-blank-people-field.formulaOrCode:
// Text
lblOwner.Text : Coalesce(ThisItem.AssignedTo.DisplayName, "Unassigned")

// Different wording by status
lblOwner.Text :
    If(
        !IsBlank(ThisItem.AssignedTo), ThisItem.AssignedTo.DisplayName,
        ThisItem.Status.Value = "New", "Waiting to be assigned",
        "No owner"
    )

// Style the fallback so it stands out
lblOwner.Color     : If(IsBlank(ThisItem.AssignedTo), RGBA(196, 49, 75, 1), RGBA(36, 36, 36, 1))
lblOwner.FontItalic: IsBlank(ThisItem.AssignedTo)

// Photo: only call the connector when there is a person
imgOwner.Image :
    If(
        IsBlank(ThisItem.AssignedTo.Email),
        SampleImage,                                    // or an uploaded generic avatar
        IfError(Office365Users.UserPhotoV2(ThisItem.AssignedTo.Email), SampleImage)
    )

// Initials circle instead of a photo (no connector calls)
lblInitials.Text :
    With(
        { n: Coalesce(ThisItem.AssignedTo.DisplayName, "?") },
        Upper(Left(n, 1) & If(" " in n, Mid(n, Find(" ", n) + 1, 1), ""))
    )

// Multi-person column
lblReviewers.Text :
    If(IsEmpty(ThisItem.Reviewers), "No reviewers", Concat(ThisItem.Reviewers, DisplayName, ", "))

// Email or Teams link only when there is someone to contact
icoMail.Visible  : !IsBlank(ThisItem.AssignedTo.Email)
icoMail.OnSelect : Launch("mailto:" & ThisItem.AssignedTo.Email)

// Filter for unassigned work
Filter(colQueue, IsBlank(AssignedTo.Email))            // on a collection
Filter(Requests, AssignedTo.Email = Blank())           // against SharePoint; test for delegation on your list

// Combo box default when editing
cmbOwner.DefaultSelectedItems : If(IsBlank(varRecord.AssignedTo), Blank(), [varRecord.AssignedTo])

use-a-conflict-warning-after-stale-edits.formulaOrCode:
// When the record is opened, remember its version
Set(varRecord, LookUp(Requests, ID = galRequests.Selected.ID));
UpdateContext({ locLoadedModified: varRecord.Modified })

// Save button OnSelect
With(
    { current: LookUp(Requests, ID = varRecord.ID) },
    If(
        IsBlank(current),
        Notify("This item has been deleted by someone else.", NotificationType.Error),

        current.Modified > locLoadedModified,
        UpdateContext({ locConflict: true, locCurrent: current }),          // show the dialog

        IfError(
            Set(varRecord, Patch(Requests, current, { Title: txtTitle.Text, Notes: txtNotes.Text }));
            UpdateContext({ locLoadedModified: varRecord.Modified });
            Notify("Saved", NotificationType.Success),
            Notify("Could not save: " & FirstError.Message, NotificationType.Error)
        )
    )
)

// Conflict dialog (Visible : locConflict)
lblConflict.Text :
    locCurrent.Editor.DisplayName & " changed this item at " & Text(locCurrent.Modified, "hh:mm") &
    ". Saving now would replace their changes."

// Show what differs
lblTheirTitle.Text : "Their title: " & locCurrent.Title
lblYourTitle.Text  : "Your title: " & txtTitle.Text

// Option 1: reload their version (discard mine)
btnReload.OnSelect :
    Set(varRecord, locCurrent);
    UpdateContext({ locLoadedModified: locCurrent.Modified, locConflict: false, locReset: true });
    UpdateContext({ locReset: false })

// Option 2: keep mine (overwrite)
btnOverwrite.OnSelect :
    Set(varRecord, Patch(Requests, locCurrent, { Title: txtTitle.Text, Notes: txtNotes.Text }));
    UpdateContext({ locLoadedModified: varRecord.Modified, locConflict: false })

// Option 3: save only the fields I changed, keeping theirs for the rest
Patch(Requests, locCurrent,
    If(txtTitle.Text <> varRecord.Title, { Title: txtTitle.Text }),
    If(txtNotes.Text <> varRecord.Notes, { Notes: txtNotes.Text }))

// Edit forms: the same situation raises an error in OnFailure
frmRequest.OnFailure :
    If(frmRequest.ErrorKind = ErrorKind.Conflict,
       Notify("Someone else changed this item. Refresh to see their changes.", NotificationType.Warning); Refresh(Requests),
       Notify(frmRequest.Error, NotificationType.Error))

use-a-reusable-validation-summary.formulaOrCode:
// Rules in one place
// btnSave.OnSelect
ClearCollect(
    colValidation,
    Filter(
        Table(
            { Key: "Title",    Tab: "Details", Bad: IsBlank(Trim(txtTitle.Text)),            Msg: "Enter a title" },
            { Key: "Title",    Tab: "Details", Bad: Len(txtTitle.Text) > 120,                Msg: "Title must be 120 characters or fewer" },
            { Key: "Email",    Tab: "Details", Bad: !IsBlank(txtEmail.Text) && !IsMatch(txtEmail.Text, Match.Email), Msg: "Enter a valid email address" },
            { Key: "Start",    Tab: "Dates",   Bad: IsBlank(dpStart.SelectedDate),           Msg: "Choose a start date" },
            { Key: "End",      Tab: "Dates",   Bad: dpEnd.SelectedDate < dpStart.SelectedDate, Msg: "End date must be on or after the start date" },
            { Key: "Amount",   Tab: "Costs",   Bad: !IsNumeric(txtAmount.Text),              Msg: "Amount must be a number" }
        ),
        Bad
    )
);
If(
    IsEmpty(colValidation),
    Select(btnDoSave),                                   // hidden button with the Patch
    UpdateContext({ locShowSummary: true })
)

// Summary box at the top of the form
conSummary.Visible : locShowSummary && !IsEmpty(colValidation)
lblSummaryTitle.Text : "Fix " & CountRows(colValidation) & If(CountRows(colValidation) = 1, " problem", " problems") & " before saving"
galSummary.Items : colValidation
lblMsg.Text      : "• " & ThisItem.Msg

// Tap a message to go to the field
galSummary.OnSelect :
    UpdateContext({ locTab: ThisItem.Tab });
    Switch(ThisItem.Key,
        "Title",  SetFocus(txtTitle),
        "Email",  SetFocus(txtEmail),
        "Start",  SetFocus(dpStart),
        "End",    SetFocus(dpEnd),
        "Amount", SetFocus(txtAmount))

// Inline markers use the same collection
txtTitle.BorderColor   : If(locShowSummary && "Title" in colValidation.Key, Color.Red, RGBA(166, 166, 166, 1))
lblTitleError.Text     : LookUp(colValidation, Key = "Title").Msg
lblTitleError.Visible  : locShowSummary && "Title" in colValidation.Key

// Re-check as the user fixes things (each input's OnChange)
If(locShowSummary, Select(btnValidateOnly))             // hidden button holding the ClearCollect

// Accessibility
conSummary.Role : "alert"        lblSummaryTitle.Live : Live.Assertive

// Reuse: a component with an input table (Key, Msg) and an OnSelectMessage behaviour property.

use-a-status-transition-matrix-in-power-.formulaOrCode:
// The matrix: a named formula, or a SharePoint list "Status Transitions" for no-code changes
nfTransitions = Table(
    { From: "Draft",             To: "Submitted",         Role: "Requester", Label: "Submit",            NeedsNote: false },
    { From: "Submitted",         To: "In review",         Role: "Reviewer",  Label: "Start review",      NeedsNote: false },
    { From: "Submitted",         To: "Draft",             Role: "Requester", Label: "Withdraw to draft", NeedsNote: false },
    { From: "In review",         To: "Approved",          Role: "Reviewer",  Label: "Approve",           NeedsNote: false },
    { From: "In review",         To: "Returned",          Role: "Reviewer",  Label: "Send back",         NeedsNote: true  },
    { From: "In review",         To: "Rejected",          Role: "Reviewer",  Label: "Reject",            NeedsNote: true  },
    { From: "Returned",          To: "Submitted",         Role: "Requester", Label: "Resubmit",          NeedsNote: false },
    { From: "Approved",          To: "Closed",            Role: "Reviewer",  Label: "Close",             NeedsNote: false },
    { From: "Closed",            To: "In review",         Role: "Admin",     Label: "Reopen",            NeedsNote: true  }
);

// The current user's roles for this record
// locRoles: a single-column table
UpdateContext({
    locRoles: Filter(
        Table(
            { Value: "Requester", Has: Lower(varRecord.Author.Email) = Lower(User().Email) },
            { Value: "Reviewer",  Has: nfIsReviewer },
            { Value: "Admin",     Has: nfIsAdmin }
        ),
        Has
    )
})

// Next steps available now (gallery of buttons)
galActions.Items :
    Filter(nfTransitions, From = varRecord.Status.Value && Role in locRoles.Value)
btnAction.Text : ThisItem.Label

// Take a step
galActions.OnSelect :
    If(
        ThisItem.NeedsNote && IsBlank(Trim(txtNote.Text)),
        Notify("Add a note for "" & ThisItem.Label & """, NotificationType.Error),
        With(
            { current: LookUp(Requests, ID = varRecord.ID), step: ThisItem },
            If(
                current.Status.Value <> step.From,
                Notify("The status has changed to " & current.Status.Value & ". Refreshing.", NotificationType.Warning);
                Set(varRecord, current),
                Set(varRecord,
                    Patch(Requests, current, {
                        Status: { Value: step.To },
                        StatusNote: Trim(txtNote.Text),
                        StatusChangedOn: Now(),
                        StatusChangedBy: User().Email
                    }));
                Reset(txtNote);
                Notify("Moved to " & step.To, NotificationType.Success)
            )
        )
    )

// No actions available
lblNoActions.Visible : IsEmpty(galActions.AllItems)
lblNoActions.Text    : "No actions are available to you at this stage."

// Same matrix can validate in a flow: Get items from the Status Transitions list and check From/To.

use-a-read-only-review-mode-before-submi.formulaOrCode:
// Mode
Screen.OnVisible : UpdateContext({ locMode: "Edit" })

// Continue button: validate, then switch to review
btnContinue.Visible  : locMode = "Edit"
btnContinue.OnSelect :
    If(
        IsBlank(Trim(txtTitle.Text)) || !IsNumeric(txtAmount.Text) || IsBlank(dpNeeded.SelectedDate),
        Notify("Complete the title, amount and date before continuing", NotificationType.Error),
        UpdateContext({ locMode: "Review" })
    )

// Option A: the same inputs become read-only
txtTitle.DisplayMode   : If(locMode = "Review", DisplayMode.View, DisplayMode.Edit)
ddCategory.DisplayMode : If(locMode = "Review", DisplayMode.View, DisplayMode.Edit)
dpNeeded.DisplayMode   : If(locMode = "Review", DisplayMode.View, DisplayMode.Edit)
// (a form: frmRequest.DisplayMode with the same expression)

// Option B: a separate summary container, usually easier to read
conEdit.Visible   : locMode = "Edit"
conReview.Visible : locMode = "Review"

lblRTitle.Text    : txtTitle.Text
lblRCategory.Text : ddCategory.Selected.Value
lblRNeeded.Text   : Text(dpNeeded.SelectedDate, "dddd d mmmm yyyy")
lblRAmount.Text   : Text(Value(txtAmount.Text), "$#,##0.00")
lblRApprover.Text : "This will go to " & gblMyManager.displayName & " for approval."
lblRWarning.Text  : If(Value(txtAmount.Text) > 5000, "Amounts over 5,000 also need finance approval.")
lblRFiles.Text    : CountRows(colFiles) & " file(s) attached"

// Heading
lblHeading.Text : If(locMode = "Review", "Check your request", "New request")

// Declaration
chkConfirm.Text    : "I confirm these details are correct"
chkConfirm.Visible : locMode = "Review"

// Back to editing (values are kept)
btnEdit.Visible  : locMode = "Review"
btnEdit.OnSelect : UpdateContext({ locMode: "Edit" }); Reset(chkConfirm)

// Submit
btnSubmit.Visible     : locMode = "Review"
btnSubmit.DisplayMode : If(chkConfirm.Value && !locBusy, DisplayMode.Edit, DisplayMode.Disabled)
btnSubmit.OnSelect :
    UpdateContext({ locBusy: true });
    IfError(
        Set(varSaved, Patch(Requests, Defaults(Requests), {
            Title: Trim(txtTitle.Text),
            Category: { Value: ddCategory.Selected.Value },
            NeededBy: dpNeeded.SelectedDate,
            Amount: Value(txtAmount.Text),
            Status: { Value: "Submitted" },
            ConfirmedOn: Now()
        }));
        Navigate(scrThanks, ScreenTransition.None, { locRecord: varSaved }),
        Notify("Could not submit: " & FirstError.Message, NotificationType.Error)
    );
    UpdateContext({ locBusy: false })
